// Extrair dados do webhook da Evolution API
const data = $input.item.json;

// Evolution API envia dados em formato específico
const event = data.event || 'MESSAGES_UPSERT';

// Dados da mensagem
const messageData = data.data || {};
const key = messageData.key || {};
const message = messageData.message || {};

// Extrair número do remetente (remover @s.whatsapp.net)
const remoteJid = key.remoteJid || '';
const telefone = remoteJid.replace('@s.whatsapp.net', '');

// Extrair texto da mensagem (vários formatos possíveis)
let textoMensagem = '';
if (message.conversation) {
  textoMensagem = message.conversation;
} else if (message.extendedTextMessage && message.extendedTextMessage.text) {
  textoMensagem = message.extendedTextMessage.text;
} else if (message.imageMessage && message.imageMessage.caption) {
  textoMensagem = message.imageMessage.caption;
} else if (message.listResponseMessage) {
  textoMensagem = message.listResponseMessage.singleSelectReply.selectedRowId;
} else if (message.buttonsResponseMessage) {
  textoMensagem = message.buttonsResponseMessage.selectedButtonId;
}

// Verificar se é mensagem enviada por você (ignore)
const fromMe = key.fromMe || false;
if (fromMe) {
  return null; // Ignorar mensagens enviadas pelo próprio bot
}

// Dados do contato
const pushName = messageData.pushName || 'Cliente';
const instanceName = data.instance || 'default';

// Debug info
console.log('Webhook recebido:', {
  event,
  telefone,
  mensagem: textoMensagem,
  fromMe,
  pushName
});

return {
  telefone: telefone,
  mensagem: textoMensagem.trim(),
  nome_cliente: pushName,
  instance: instanceName,
  event: event,
  raw_data: data
};

// Sistema de gerenciamento de estado da conversa
const telefone = $input.item.json.telefone;
const mensagem = $input.item.json.mensagem;
const nomeCliente = $input.item.json.nome_cliente;

// Simular banco de dados de sessões (em produção, usar Redis/MongoDB)
if (!$execution.customData) {
  $execution.customData = {};
}

if (!$execution.customData[telefone]) {
  $execution.customData[telefone] = {
    etapa: 'inicio',
    dados: { nome: nomeCliente }
  };
}

const sessao = $execution.customData[telefone];
let proximaEtapa = sessao.etapa;
let resposta = '';
let concluido = false;

// Comandos especiais
if (mensagem.toLowerCase() === 'reiniciar' || mensagem.toLowerCase() === 'menu') {
  sessao.etapa = 'inicio';
  sessao.dados = { nome: nomeCliente };
  proximaEtapa = 'inicio';
}

// Máquina de estados do fluxo
switch(sessao.etapa) {
  case 'inicio':
    resposta = `Olá ${nomeCliente}! 👋\n\nBem-vindo à nossa imobiliária!\n\nVou te ajudar a encontrar o imóvel perfeito.\n\nVocê está buscando:\n\n*1* - Aluguel\n*2* - Compra\n\nResponda com o número da opção:`;
    proximaEtapa = 'tipo_negocio';
    break;

  case 'tipo_negocio':
    if (mensagem === '1') {
      sessao.dados.tipo = 'aluguel';
      resposta = `Ótimo! 💰\n\n*Aluguel* selecionado.\n\nQual sua faixa de orçamento mensal?\n\n*1* - Até R$ 1.500\n*2* - R$ 1.500 a R$ 3.000\n*3* - R$ 3.000 a R$ 5.000\n*4* - Acima de R$ 5.000\n\nResponda com o número:`;
    } else if (mensagem === '2') {
      sessao.dados.tipo = 'compra';
      resposta = `Ótimo! 🏠\n\n*Compra* selecionada.\n\nQual sua faixa de investimento?\n\n*1* - Até R$ 500.000\n*2* - R$ 500.000 a R$ 1.000.000\n*3* - R$ 1.000.000 a R$ 2.000.000\n*4* - Acima de R$ 2.000.000\n\nResponda com o número:`;
    } else {
      resposta = '❌ Por favor, responda com *1* para Aluguel ou *2* para Compra.';
      proximaEtapa = 'tipo_negocio';
      break;
    }
    proximaEtapa = 'orcamento';
    break;

  case 'orcamento':
    const faixas = {
      '1': { codigo: sessao.dados.tipo === 'aluguel' ? 'ate_1500' : 'ate_500k', nome: sessao.dados.tipo === 'aluguel' ? 'Até R$ 1.500' : 'Até R$ 500.000' },
      '2': { codigo: sessao.dados.tipo === 'aluguel' ? '1500_3000' : '500k_1m', nome: sessao.dados.tipo === 'aluguel' ? 'R$ 1.500 a R$ 3.000' : 'R$ 500k a R$ 1M' },
      '3': { codigo: sessao.dados.tipo === 'aluguel' ? '3000_5000' : '1m_2m', nome: sessao.dados.tipo === 'aluguel' ? 'R$ 3.000 a R$ 5.000' : 'R$ 1M a R$ 2M' },
      '4': { codigo: sessao.dados.tipo === 'aluguel' ? 'acima_5000' : 'acima_2m', nome: sessao.dados.tipo === 'aluguel' ? 'Acima de R$ 5.000' : 'Acima de R$ 2M' }
    };

    if (faixas[mensagem]) {
      sessao.dados.faixa_preco = faixas[mensagem].codigo;
      sessao.dados.faixa_nome = faixas[mensagem].nome;
      resposta = `Perfeito! 💰\n\n*Faixa selecionada*: ${faixas[mensagem].nome}\n\nQuantos *dormitórios* você precisa?\n\n*1* - 1 dormitório\n*2* - 2 dormitórios\n*3* - 3 dormitórios\n*4* - 4 ou mais\n\nResponda com o número:`;
      proximaEtapa = 'dormitorios';
    } else {
      resposta = '❌ Por favor, escolha uma opção entre *1* e *4*.';
    }
    break;

  case 'dormitorios':
    if (['1', '2', '3', '4'].includes(mensagem)) {
      sessao.dados.dormitorios = mensagem === '4' ? '4+' : mensagem;
      resposta = `Ótimo! 🛏️\n\n*${mensagem === '4' ? '4+' : mensagem} ${mensagem === '1' ? 'dormitório' : 'dormitórios'}*\n\nQual tipo de imóvel?\n\n*1* - Apartamento\n*2* - Casa térrea\n*3* - Sobrado\n*4* - Cobertura\n*5* - Qualquer tipo\n\nResponda com o número:`;
      proximaEtapa = 'tipo_imovel';
    } else {
      resposta = '❌ Por favor, escolha uma opção entre *1* e *4*.';
    }
    break;

  case 'tipo_imovel':
    const tipos = {
      '1': 'apartamento',
      '2': 'casa_terrea',
      '3': 'sobrado',
      '4': 'cobertura',
      '5': 'qualquer'
    };

    if (tipos[mensagem]) {
      sessao.dados.tipo_imovel = tipos[mensagem];
      resposta = `Legal! 🏠\n\nPreferência de *sala*:\n\n*1* - Sala integrada (conceito aberto)\n*2* - Sala separada\n*3* - Tanto faz\n\nResponda com o número:`;
      proximaEtapa = 'sala';
    } else {
      resposta = '❌ Por favor, escolha uma opção entre *1* e *5*.';
    }
    break;

  case 'sala':
    const tiposSala = {
      '1': 'integrada',
      '2': 'separada',
      '3': 'tanto_faz'
    };

    if (tiposSala[mensagem]) {
      sessao.dados.tipo_sala = tiposSala[mensagem];
      resposta = `Entendido! 🚗\n\n*Vagas de garagem*:\n\n*1* - 1 vaga\n*2* - 2 vagas\n*3* - 3 ou mais vagas\n*4* - Não preciso\n\nResponda com o número:`;
      proximaEtapa = 'vagas';
    } else {
      resposta = '❌ Por favor, escolha uma opção entre *1* e *3*.';
    }
    break;

  case 'vagas':
    if (['1', '2', '3', '4'].includes(mensagem)) {
      sessao.dados.vagas = mensagem === '4' ? '0' : mensagem;
      resposta = `Ótimo! 📍\n\nPor fim, qual *região* você prefere?\n\nDigite o nome do bairro ou região:\n\n_Exemplo: Centro, Zona Sul, Jardins, etc._`;
      proximaEtapa = 'localizacao';
    } else {
      resposta = '❌ Por favor, escolha uma opção entre *1* e *4*.';
    }
    break;

  case 'localizacao':
    sessao.dados.localizacao = mensagem;
    resposta = `Perfeito! ✅\n\n━━━━━━━━━━━━━━━━━━\n*RESUMO DA SUA BUSCA*\n━━━━━━━━━━━━━━━━━━\n\n📋 *Tipo*: ${sessao.dados.tipo}\n💰 *Faixa*: ${sessao.dados.faixa_nome}\n🛏️ *Dormitórios*: ${sessao.dados.dormitorios}\n🏠 *Imóvel*: ${sessao.dados.tipo_imovel}\n🪟 *Sala*: ${sessao.dados.tipo_sala}\n🚗 *Vagas*: ${sessao.dados.vagas}\n📍 *Região*: ${sessao.dados.localizacao}\n\n━━━━━━━━━━━━━━━━━━\n\n🔍 Buscando imóveis...\n\n_Aguarde um momento, por favor._`;
    proximaEtapa = 'buscar';
    concluido = true;
    break;

  default:
    resposta = '❌ Erro no fluxo.\n\nDigite *menu* para começar novamente.';
    if (mensagem.toLowerCase() === 'menu' || mensagem.toLowerCase() === 'reiniciar') {
      proximaEtapa = 'inicio';
      sessao.dados = { nome: nomeCliente };
    }
}

// Atualizar estado
sessao.etapa = proximaEtapa;
$execution.customData[telefone] = sessao;

return {
  telefone: telefone,
  resposta: resposta,
  etapa_atual: proximaEtapa,
  dados_coletados: sessao.dados,
  buscar_imoveis: concluido,
  instance: $input.item.json.instance
};

// Processar resultados e montar mensagem de resposta
const dados = $input.first().json;
const imoveis = dados.imoveis || [];
const telefone = $('Lógica Conversacional').first().json.telefone;
const instance = $('Lógica Conversacional').first().json.instance;

let mensagemFinal = '';

if (imoveis.length === 0) {
  mensagemFinal = `😔 *Nenhum imóvel encontrado*\n\n━━━━━━━━━━━━━━━━━━\n\nInfelizmente não encontrei imóveis disponíveis com esses critérios no momento.\n\nMas não se preocupe! 💪\n\n✅ Vou registrar seu interesse\n✅ Nossa equipe entrará em contato quando tivermos opções\n\n━━━━━━━━━━━━━━━━━━\n\n📞 *Contato direto*:\nTelefone: (11) 9999-9999\nEmail: contato@imobiliaria.com.br\n\n━━━━━━━━━━━━━━━━━━\n\nDigite *menu* para fazer nova busca.\n\nObrigado! 🏠`;
} else {
  mensagemFinal = `🎉 *Imóveis Encontrados!*\n\n━━━━━━━━━━━━━━━━━━\n\nEncontrei *${imoveis.length}* ${imoveis.length === 1 ? 'imóvel' : 'imóveis'} perfeito${imoveis.length === 1 ? '' : 's'} para você!\n\n`;

  // Adicionar detalhes de cada imóvel (máximo 3 por mensagem)
  const imoveisParaMostrar = imoveis.slice(0, 3);

  imoveisParaMostrar.forEach((imovel, index) => {
    mensagemFinal += `\n━━━━━━━━━━━━━━━━━━\n`;
    mensagemFinal += `\n🏡 *${imovel.titulo}*\n\n`;
    mensagemFinal += `📍 ${imovel.endereco}\n`;

    // Formatar preço
    const precoFormatado = new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
      minimumFractionDigits: 0
    }).format(imovel.preco);

    mensagemFinal += `💰 *${precoFormatado}*\n`;
    mensagemFinal += `🛏️ ${imovel.dormitorios} ${imovel.dormitorios === 1 ? 'dormitório' : 'dormitórios'}\n`;
    mensagemFinal += `🚗 ${imovel.vagas} ${imovel.vagas === 1 ? 'vaga' : 'vagas'}\n`;
    mensagemFinal += `📐 ${imovel.area_m2}m²\n`;

    if (imovel.caracteristicas) {
      const detalhes = [];
      if (imovel.caracteristicas.mobiliado) detalhes.push('✨ Mobiliado');
      if (imovel.caracteristicas.aceita_pets) detalhes.push('🐾 Aceita pets');
      if (imovel.caracteristicas.piscina) detalhes.push('🏊 Piscina');
      if (imovel.caracteristicas.academia) detalhes.push('💪 Academia');
      if (detalhes.length > 0) {
        mensagemFinal += `\n${detalhes.join(' • ')}\n`;
      }
    }

    mensagemFinal += `\n🔗 ${imovel.link}\n`;

    if (imovel.descricao) {
      const descShort = imovel.descricao.substring(0, 100);
      mensagemFinal += `\n_${descShort}${imovel.descricao.length > 100 ? '...' : ''}_\n`;
    }
  });

  if (imoveis.length > 3) {
    mensagemFinal += `\n━━━━━━━━━━━━━━━━━━\n`;
    mensagemFinal += `\n➕ *E mais ${imoveis.length - 3} ${imoveis.length - 3 === 1 ? 'imóvel' : 'imóveis'}!*\n`;
  }

  mensagemFinal += `\n━━━━━━━━━━━━━━━━━━\n\n📞 *Agendar visita?*\nLigue: (11) 9999-9999\n\n━━━━━━━━━━━━━━━━━━\n\nDigite *menu* para nova busca! 🔍`;
}

return {
  telefone: telefone,
  mensagem: mensagemFinal,
  total_imoveis: imoveis.length,
  imoveis: imoveis,
  instance: instance
};
